describe('parseJevCategoryAnswer', () => {
  it('parses choice, confidence, in-set probabilities and input tokens', () => {
    const parsed = parseJevCategoryAnswer(answerBody('bugfix'));
    expect(parsed).toEqual({
      category: 'bugfix',
      confidence: 0.82,
      probabilities: { bugfix: 0.85, feature: 0.1, docs: 0.05 },
      inputTokens: 312,
    });
  });

  it('rejects a choice outside the closed set and malformed bodies', () => {
    expect(parseJevCategoryAnswer(answerBody('other'))).toBeNull();
    expect(parseJevCategoryAnswer(null)).toBeNull();
    expect(parseJevCategoryAnswer({ answers: {} })).toBeNull();
    expect(parseJevCategoryAnswer({ answers: { [JEV_QUESTION_ID]: 'bugfix' } })).toBeNull();
  });

  it('treats non-finite and out-of-range confidence as unavailable', () => {
    for (const confidence of [Number.NaN, Number.POSITIVE_INFINITY, -0.01, 1.01]) {
      expect(parseJevCategoryAnswer(answerBody('docs', { confidence }))?.confidence).toBeNull();
    }
  });
});

describe('classifyCategoryWithJev (mocked HTTP)', () => {
  it('POSTs the Choice with a bearer key and returns the typed answer', async () => {
    const fetchImpl = mockFetch(200, answerBody('bugfix'), { 'x-typesafe-request-id': 'req_1' });
    let t = 1000;
    const result = await classifyCategoryWithJev({
      firstPrompt: 'the login page 404s after sign in',
      branch: 'fix/login',
      apiKey: KEY,
      fetchImpl,
      now: () => (t += 120),
    });
    expect(result).toMatchObject({
      ok: true,
      category: 'bugfix',
      confidence: 0.82,
      inputTokens: 312,
      requestId: 'req_1',
      latencyMs: 120,
    });
    const [url, init] = vi.mocked(fetchImpl).mock.calls[0] as [string, RequestInit];
    expect(url).toBe(JEV_ENDPOINT);
    expect(init.method).toBe('POST');
    expect((init.headers as Record<string, string>).Authorization).toBe(`Bearer ${KEY}`);
    const sent = JSON.parse(String(init.body));
    expect(Object.keys(sent.questions[JEV_QUESTION_ID].criteria)).toEqual([...WORK_CATEGORIES]);
  });

  it('fails open on a non-2xx status', async () => {
    const result = await classifyCategoryWithJev({
      firstPrompt: 'p',
      branch: '',
      apiKey: KEY,
      fetchImpl: mockFetch(429, { error: 'rate limited' }),
    });
    expect(result).toMatchObject({ ok: false, error: 'http 429', status: 429 });
  });

  it('fails open on a malformed answer', async () => {
    const result = await classifyCategoryWithJev({
      firstPrompt: 'p',
      branch: '',
      apiKey: KEY,
      fetchImpl: mockFetch(200, { answers: {} }),
    });
    expect(result).toMatchObject({ ok: false, error: 'malformed answer' });
  });

  it('fails open when fetch throws, without echoing the key', async () => {
    const fetchImpl = vi.fn(async () => {
      throw new TypeError(`network down ${KEY}`);
    }) as unknown as typeof fetch;
    const result = await classifyCategoryWithJev({ firstPrompt: 'p', branch: '', apiKey: KEY, fetchImpl });
    expect(result).toMatchObject({ ok: false, error: 'TypeError', status: null });
    expect(JSON.stringify(result)).not.toContain(KEY);
  });

  it('aborts at the timeout and reports it as a timeout', async () => {
    const fetchImpl = vi.fn(
      (_url: string, init: RequestInit) =>
        new Promise<Response>((_resolve, reject) => {
          init.signal?.addEventListener('abort', () => reject(new DOMException('aborted', 'AbortError')));
        }),
    ) as unknown as typeof fetch;
    const result = await classifyCategoryWithJev({
      firstPrompt: 'p',
      branch: '',
      apiKey: KEY,
      fetchImpl,
      timeoutMs: 20,
    });
    expect(result).toMatchObject({ ok: false, error: 'timeout' });
  });
});

describe('shadow files', () => {
  let tmpDir: string;
  let jevPath: string;
  let shadowPath: string;

  beforeEach(() => {
    tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'category-shadow-'));
    jevPath = path.join(tmpDir, 'session-identity.jev.json');
    shadowPath = path.join(tmpDir, 'session-identity.shadow.json');
  });

  afterEach(() => {
    fs.rmSync(tmpDir, { recursive: true, force: true });
  });

  const JEV = { [CATEGORY_PROVIDER_ENV]: 'jev', [TYPESAFE_KEY_ENV]: KEY };
  const SHADOW = { [CATEGORY_PROVIDER_ENV]: 'shadow', [TYPESAFE_KEY_ENV]: KEY };

  it('startJevCategory writes the result without the key or the prompt, then hands it to onResult', async () => {
    const secretPrompt = 'private prompt text that must not be stored';
    const seen: JevCategoryResult[] = [];
    await startJevCategory(secretPrompt, 'feat/x', jevPath, JEV, mockFetch(200, answerBody('feature')), (r) =>
      seen.push(r),
    );
    const written = fs.readFileSync(jevPath, 'utf8');
    expect(JSON.parse(written)).toMatchObject({ ok: true, category: 'feature', model: JEV_MODEL });
    expect(written).not.toContain(KEY);
    expect(written).not.toContain(secretPrompt);
    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({ ok: true, category: 'feature', confidence: 0.82 });
  });

  it('readJevDecision reads the settled file back through the same rule', async () => {
    await startJevCategory('p', 'b', jevPath, JEV, mockFetch(200, answerBody('feature')));
    expect(readJevDecision(jevPath, JEV)).toEqual({ category: 'feature', confidence: 0.82 });
    expect(readJevDecision(jevPath, SHADOW)).toBeNull();
    expect(readJevDecision(path.join(tmpDir, 'missing.json'), JEV)).toBeNull();
    fs.writeFileSync(jevPath, '{not json', 'utf8');
    expect(readJevDecision(jevPath, JEV)).toBeNull();
  });

  it('fails open for malformed and out-of-range persisted confidences', () => {
    fs.writeFileSync(
      jevPath,
      JSON.stringify({ ok: true, model: JEV_MODEL, category: 'docs', confidence: 1.01, latencyMs: 210 }),
    );
    expect(readJevResult(jevPath)).toMatchObject({ ok: true, confidence: null });
    expect(readJevDecision(jevPath, JEV)).toBeNull();
    fs.writeFileSync(jevPath, '{"ok":true,"category":"docs","confidence":NaN}', 'utf8');
    expect(readJevResult(jevPath)).toBeNull();
    expect(readJevDecision(jevPath, JEV)).toBeNull();
  });

  it('records the pair once haiku settles, and only once, with decided_by=jev when confident', () => {
    fs.writeFileSync(
      jevPath,
      JSON.stringify({ ok: true, model: JEV_MODEL, category: 'docs', confidence: 0.9, latencyMs: 210, inputTokens: 400 }),
    );
    expect(recordCategoryShadow(jevPath, shadowPath, null, false, JEV)).toBeNull();
    const record = recordCategoryShadow(jevPath, shadowPath, 'infra', true, JEV);
    expect(record).toMatchObject({
      provider: 'jev',
      haiku: 'infra',
      jev: 'docs',
      agree: false,
      jev_confidence: 0.9,
      high_confidence_disagreement: true,
      below_floor: false,
      decided_by: 'jev',
      threshold: 0.8,
      latency_ms: 210,
      input_tokens: 400,
      error: null,
    });
    expect(recordCategoryShadow(jevPath, shadowPath, 'infra', true, JEV)).toBeNull();
  });

  it('records decided_by=haiku below the threshold and in shadow mode', () => {
    fs.writeFileSync(jevPath, JSON.stringify({ ok: true, model: JEV_MODEL, category: 'docs', confidence: 0.6, latencyMs: 210 }));
    expect(recordCategoryShadow(jevPath, shadowPath, 'infra', true, JEV)).toMatchObject({
      provider: 'jev',
      decided_by: 'haiku',
      jev_confidence: 0.6,
      high_confidence_disagreement: false,
      below_floor: true,
    });
    fs.rmSync(shadowPath);
    fs.writeFileSync(jevPath, JSON.stringify({ ok: true, model: JEV_MODEL, category: 'docs', confidence: 0.99, latencyMs: 210 }));
    expect(recordCategoryShadow(jevPath, shadowPath, 'infra', true, SHADOW)).toMatchObject({
      provider: 'shadow',
      decided_by: 'haiku',
      jev_confidence: 0.99,
    });
  });

  it('derives high-confidence disagreement and below-floor from the effective per-seam floor', () => {
    fs.writeFileSync(
      jevPath,
      JSON.stringify({ ok: true, model: JEV_MODEL, category: 'docs', confidence: 0.9, latencyMs: 210 }),
    );
    const floor095 = { ...JEV, [CATEGORY_JEV_FLOOR_ENV]: '0.95' };
    expect(recordCategoryShadow(jevPath, shadowPath, 'infra', true, floor095)).toMatchObject({
      threshold: 0.95,
      high_confidence_disagreement: false,
      below_floor: true,
      decided_by: 'haiku',
    });
  });

  it('records a failed Jev call with its error, agree=null and decided_by=haiku', () => {
    fs.writeFileSync(jevPath, JSON.stringify({ ok: false, error: 'timeout', status: null, latencyMs: 1500 }));
    expect(recordCategoryShadow(jevPath, shadowPath, 'bugfix', true, JEV)).toMatchObject({
      haiku: 'bugfix',
      jev: null,
      agree: null,
      decided_by: 'haiku',
      error: 'timeout',
    });
  });

  it('does nothing while the Jev result has not landed', () => {
    expect(recordCategoryShadow(jevPath, shadowPath, 'bugfix', true, JEV)).toBeNull();
    expect(fs.existsSync(shadowPath)).toBe(false);
  });
});
